(function(){'use strict';
var KEY='welog-split-area-crop-v1';
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'null')||{top:0,right:0,bottom:0,left:0}}catch(e){return{top:0,right:0,bottom:0,left:0}}}
function clamp(v){v=Number(v)||0;return Math.max(0,Math.min(45,v))}
function save(c){try{localStorage.setItem(KEY,JSON.stringify(c))}catch(e){}}
function apply(c){c=c||read();['top','right','bottom','left'].forEach(function(k){c[k]=clamp(c[k])});document.documentElement.style.setProperty('--welog-split-crop-top',c.top+'%');document.documentElement.style.setProperty('--welog-split-crop-right',c.right+'%');document.documentElement.style.setProperty('--welog-split-crop-bottom',c.bottom+'%');document.documentElement.style.setProperty('--welog-split-crop-left',c.left+'%');document.querySelectorAll('[data-welog-crop-value]').forEach(function(o){var k=o.dataset.welogCropValue;o.textContent=c[k]+'%'});save(c)}
function isSplit(){var checked=document.querySelector('input[name="centerMode"]:checked');return !!(checked&&checked.dataset.centerMode==='split')}
function ensure(){var controls=document.getElementById('controls');if(!controls)return;var row=controls.querySelector('.center-mode-check');var box=controls.querySelector('.welog-split-area-control');if(!row){if(box)box.hidden=true;return}if(!box){var c=read();box=document.createElement('section');box.className='welog-split-area-control';box.innerHTML='<div class="welog-split-head"><b>분리 중앙 이미지 영역 자르기</b><span>이미지 크기는 유지하고 보이는 영역만 자릅니다.</span></div>'+['top','bottom','left','right'].map(function(k){var label={top:'위',bottom:'아래',left:'왼쪽',right:'오른쪽'}[k];return '<label class="welog-split-crop-row"><span>'+label+'</span><input type="range" min="0" max="45" step="1" data-welog-crop="'+k+'" value="'+clamp(c[k])+'"><output data-welog-crop-value="'+k+'">'+clamp(c[k])+'%</output></label>'}).join('')+'<button type="button" data-welog-crop-reset>자르기 초기화</button><small>두 이미지가 들어가는 중앙 영역 자체를 위·아래·좌·우에서 잘라냅니다. 확대/축소가 아닙니다.</small>';row.insertAdjacentElement('afterend',box);box.addEventListener('input',function(e){var k=e.target.dataset.welogCrop;if(!k)return;var next=read();next[k]=clamp(e.target.value);apply(next)});box.querySelector('[data-welog-crop-reset]').addEventListener('click',function(){var z={top:0,right:0,bottom:0,left:0};box.querySelectorAll('[data-welog-crop]').forEach(function(r){r.value=0});apply(z)})}box.hidden=!isSplit();apply(read())}
var controls=document.getElementById('controls');if(controls)new MutationObserver(function(){ensure()}).observe(controls,{childList:true,subtree:false});document.addEventListener('change',function(e){if(e.target&&e.target.name==='centerMode')setTimeout(ensure,0)},true);document.addEventListener('click',function(e){if(e.target.closest&&e.target.closest('#tabs'))setTimeout(ensure,0)},true);apply(read());ensure();
})();